            _ = try self.finishSpawn((&spawned), ipc_output_fds[0], .{ .buffer = pipe });
    }

pub fn finishSpawn(self: *SecurityScanSubprocess, spawned: anytype, ipc_read_fd: bun.FD, json_stdio_result: jsc.Subprocess.StdioResult) !void {
            const json_data_copy = try self.manager.allocator.dupe(u8, self.json_data);
            const json_source = jsc.Subprocess.Source{ .blob = jsc.WebCore.Blob.Any.fromOwnedSlice(self.manager.allocator, json_data_copy) };
            self.remaining_fds = 2;
            _ = try self.ipc_reader.start(ipc_read_fd, true).unwrap();
            var process = spawned.toProcess((&self.manager.event_loop), false);
            _ = &process;
            self.process = process;
            _ = (process).?.setExitHandler(self);
            self.json_writer = StaticPipeWriter.create((&self.manager.event_loop), self, json_stdio_result, json_source);
            errdefer {
            {
                if (self.json_writer) |writer| {
                    _ = &writer;
                    _ = writer.source.detach();
                    _ = writer.deref();
                    self.json_writer = null;
                }
            }
            }
            switch (self.json_writer.?.start()) {
.err => |e| {
_ = Output.errGeneric("Failed to start security scanner JSON pipe writer: {f}", .{ e });
            return error.JSONPipeWriterFailed;
},
.result => {

},
}
            switch ((process).?.watchOrReap()) {
.err => {
return error.ProcessWatchFailed;
},
.result => {

},
}
    }

pub fn onCloseIO(self: *SecurityScanSubprocess, _: jsc.Subprocess.StdioKind) void {
            if (self.json_writer) |writer| {
                _ = &writer;
                _ = writer.source.detach();
                _ = writer.deref();
                self.json_writer = null;
                self.remaining_fds = (self.remaining_fds - 1);
            }
    }

pub fn isDone(self: *SecurityScanSubprocess) bool {
            return (self.has_process_exited and (self.remaining_fds == 0));
    }

pub fn eventLoop(self: SecurityScanSubprocess) *jsc.AnyEventLoop {
            return (&self.manager.event_loop);
    }

pub fn loop(self: SecurityScanSubprocess) *bun.Async.Loop {
            if (comptime bun.Environment.isWindows) {
                return self.manager.event_loop.loop().uv_loop;
            }
            return self.manager.event_loop.loop();
    }

pub fn onReaderDone(self: *SecurityScanSubprocess) void {
            self.has_received_ipc = true;
            self.remaining_fds = (self.remaining_fds - 1);
    }

pub fn onReaderError(self: *SecurityScanSubprocess, e: bun.sys.Error) void {
            _ = Output.errGeneric("Failed to read security scanner IPC: {f}", .{ e });
            self.has_received_ipc = true;
            self.remaining_fds = (self.remaining_fds - 1);
    }

pub fn onStderrChunk(self: *SecurityScanSubprocess, chunk: []const u8) void {
            _ = bun.handleOom(self.stderr_data.appendSlice(self.manager.allocator, chunk));
    }

pub fn getReadBuffer(self: *SecurityScanSubprocess) []u8 {
            const available = self.ipc_data.unusedCapacitySlice();
            if ((available.len < 4096)) {
                _ = bun.handleOom(self.ipc_data.ensureTotalCapacity(self.manager.allocator, (self.ipc_data.capacity + 4096)));
                return self.ipc_data.unusedCapacitySlice();
            }
            return available;
    }

pub fn onReadChunk(self: *SecurityScanSubprocess, chunk: []const u8, hasMore: bun.io.ReadState) bool {
            _ = &hasMore;
            _ = bun.handleOom(self.ipc_data.appendSlice(self.manager.allocator, chunk));
            return true;
    }

pub fn onProcessExit(self: *SecurityScanSubprocess, _: *bun.spawn.Process, status: bun.spawn.Status, _: *const bun.spawn.Rusage) void {
            self.has_process_exited = true;
            self.exit_status = status;
            if ((!self.has_received_ipc)) {
                _ = self.ipc_reader.deinit();
                self.remaining_fds = (self.remaining_fds - 1);
            }
    }

pub fn handleResults(self: *SecurityScanSubprocess, package_paths: *std.AutoArrayHashMap(PackageID,PackagePath), start_time: i64, packages_scanned: usize, security_scanner: []const u8, security_scanner_pkg_id: ?PackageID, command_ctx: bun.cli.Command.Context, original_cwd: []const u8, is_retry: bool) !ScanAttemptResult {
            _ = &command_ctx;
            _ = &original_cwd;
            defer {
            {
                _ = self.ipc_data.deinit(self.manager.allocator);
                _ = self.stderr_data.deinit(self.manager.allocator);
            }
            }
            if ((self.exit_status == null)) {
                _ = Output.errGeneric("Security scanner terminated without an exit status. This is a bug in Bun.", .{});
                return error.SecurityScannerProcessFailedWithoutExitStatus;
            }
            const status = self.exit_status.?;
            if ((self.ipc_data.items.len == 0)) {
                switch (status) {
.exited => |exit| {
_ = Output.errGeneric("Security scanner exited with code {d} without sending data", .{ exit.code });
},
.signaled => |sig| {
_ = Output.errGeneric("Security scanner terminated by signal {s} without sending data", .{ @tagName(sig) });
},
else => {
_ = Output.errGeneric("Security scanner terminated abnormally without sending data", .{});
},
}
                return error.NoSecurityScanData;
            }
            const json_source = logger.Source{ .contents = self.ipc_data.items, .path = bun.fs.Path.init("ipc-message.json") };
            var temp_log = logger.Log.init(self.manager.allocator);
            _ = &temp_log;
            defer {
            _ = temp_log.deinit();
            }
            const json_expr = (blk_catch_2: { break :blk_catch_2 ((bun.json.parseUTF8((&json_source), (&temp_log), self.manager.allocator)) catch |e| { _ = &e; _ = Output.errGeneric("Security scanner sent invalid JSON: {s}", .{ @errorName(e) });
            if ((self.ipc_data.items.len < 1000)) {
                _ = Output.errGeneric("Response: {s}", .{ self.ipc_data.items });
            }
            return error.InvalidIPCMessage; }); });
            if ((json_expr.data != .e_object)) {
                _ = Output.errGeneric("Security scanner IPC message must be a JSON object", .{});
                return error.InvalidIPCFormat;
            }
            const obj = json_expr.data.e_object;
            const type_expr_opt = obj.get("type");
            if ((type_expr_opt == null)) {
                _ = Output.errGeneric("Security scanner IPC message missing 'type' field", .{});
                return error.MissingIPCType;
            }
            const type_expr = type_expr_opt.?;
            const type_str_opt = type_expr.asString(self.manager.allocator);
            if ((type_str_opt == null)) {
                _ = Output.errGeneric("Security scanner IPC 'type' must be a string", .{});
                return error.InvalidIPCType;
            }
            const type_str = type_str_opt.?;
            if (std.mem.eql(u8, type_str, "error")) {
                const code_expr_opt = obj.get("code");
                if ((code_expr_opt == null)) {
                    _ = Output.errGeneric("Security scanner error missing 'code' field", .{});
                    return error.MissingErrorCode;
                }
                const code_expr = code_expr_opt.?;
                const code_str_opt = code_expr.asString(self.manager.allocator);
                if ((code_str_opt == null)) {
                    _ = Output.errGeneric("Security scanner error 'code' must be a string", .{});
                    return error.InvalidErrorCode;
                }
                const code_str = code_str_opt.?;
                const error_code = std.@"meta".stringToEnum(SecurityScannerErrorCode, code_str);
                if ((error_code == null)) {
                    _ = Output.errGeneric("Unknown security scanner error code: {s}", .{ code_str });
                    return error.UnknownErrorCode;
                }
                switch (error_code.?) {
.MODULE_NOT_FOUND => {
if (is_retry) {
                    const is_package_name = bun.resolver.isPackagePath(security_scanner);
                    if (is_package_name) {
                        _ = Output.errGeneric("Security scanner '{s}' could not be found after installation attempt.\n  <d>If this is a local file, please check that the file exists and the path is correct.<r>", .{ security_scanner });
                        return error.SecurityScannerNotFound;
                    } else {
                        _ = Output.errGeneric("Security scanner '{s}' is configured in bunfig.toml but the file could not be found.\n  <d>Please check that the file exists and the path is correct.<r>", .{ security_scanner });
                        return error.SecurityScannerNotFound;
                    }
                }
                if (security_scanner_pkg_id) |pkg_id| {
                    _ = &pkg_id;
                    return ScanAttemptResult{ .needs_install = pkg_id };
                } else {
                    const is_package_name = bun.resolver.isPackagePath(security_scanner);
                    if (is_package_name) {
                        _ = Output.errGeneric("Security scanner '{s}' is configured in bunfig.toml but is not installed.\n  <d>To install it, run: bun add --dev {s}<r>", .{ security_scanner, security_scanner });
                    } else {
                        _ = Output.errGeneric("Security scanner '{s}' is configured in bunfig.toml but the file could not be found.\n  <d>Please check that the file exists and the path is correct.<r>", .{ security_scanner });
                    }
                    return error.SecurityScannerNotInDependencies;
                }
},
.INVALID_VERSION => {
if (obj.get("message")) |msg| {
                    _ = &msg;
                    if (msg.asString(self.manager.allocator)) |msg_str| {
                        _ = &msg_str;
                        _ = Output.errGeneric("Security scanner error: {s}", .{ msg_str });
                    }
                }
                return error.InvalidScannerVersion;
},
.SCAN_FAILED => {
if (obj.get("message")) |msg| {
                    _ = &msg;
                    if (msg.asString(self.manager.allocator)) |msg_str| {
                        _ = &msg_str;
                        _ = Output.errGeneric("Security scanner failed: {s}", .{ msg_str });
                    }
                }
                return error.ScannerFailed;
},
}
            } else {
                if ((!std.mem.eql(u8, type_str, "result"))) {
                    _ = Output.errGeneric("Unknown security scanner message type: {s}", .{ type_str });
                    return error.UnknownMessageType;
                }
            }
            const duration = (std.time.milliTimestamp() - start_time);
            if ((self.manager.options.log_level == .verbose)) {
                switch (status) {
.exited => |exit| {
if ((exit.code == 0)) {
                    _ = Output.prettyErrorln("<d>[SecurityProvider]<r> Completed with exit code {d} [{d}ms]", .{ exit.code, duration });
                } else {
                    _ = Output.prettyErrorln("<d>[SecurityProvider]<r> Failed with exit code {d} [{d}ms]", .{ exit.code, duration });
                }
},
.signaled => |sig| {
_ = Output.prettyErrorln("<d>[SecurityProvider]<r> Terminated by signal {s} [{d}ms]", .{ @tagName(sig), duration });
},
else => {
_ = Output.prettyErrorln("<d>[SecurityProvider]<r> Completed with unknown status [{d}ms]", .{ duration });
},
}
            } else {
                if (((self.manager.options.log_level != .silent) and (duration >= 1000))) {
                    const maybeHourglass = (if (Output.enable_ansi_colors_stderr) "⏳" else "");
                    if ((packages_scanned == 1)) {
                        _ = Output.prettyErrorln("<d>{s}[{s}] Scanning 1 package took {d}ms<r>", .{ maybeHourglass, security_scanner, duration });
                    } else {
                        _ = Output.prettyErrorln("<d>{s}[{s}] Scanning {d} packages took {d}ms<r>", .{ maybeHourglass, security_scanner, packages_scanned, duration });
                    }
                }
            }
            const advisories_expr_opt = obj.get("advisories");
            if ((advisories_expr_opt == null)) {
                _ = Output.errGeneric("Security scanner result missing 'advisories' field", .{});
                return error.MissingAdvisoriesField;
            }
            const advisories_expr = advisories_expr_opt.?;
            const advisories = try parseSecurityAdvisoriesFromExpr(self.manager, advisories_expr, package_paths);
            if ((!status.isOK())) {
                switch (status) {
.exited => |exited| {
if ((exited.code != 0)) {
                    _ = Output.errGeneric("Security scanner failed with exit code: {d}", .{ exited.code });
                    return error.SecurityScannerFailed;
                }
},
.signaled => |signal| {
_ = Output.errGeneric("Security scanner was terminated by signal: {s}", .{ @tagName(signal) });
                return error.SecurityScannerTerminated;
},
else => {
_ = Output.errGeneric("Security scanner failed", .{});
                return error.SecurityScannerFailed;
},
}
            }
            var fatal_count: usize = 0;
            _ = &fatal_count;
            var warn_count: usize = 0;
            _ = &warn_count;
            for (cp_iter_slice(advisories)) |advisory| {
                _ = &advisory;
                switch (advisory.level) {
.fatal => {
fatal_count = (fatal_count + 1);
},
.warn => {
warn_count = (warn_count + 1);
},
}
            }
            return ScanAttemptResult{ .success = SecurityScanResults{ .advisories = advisories, .fatal_count = fatal_count, .warn_count = warn_count, .packages_scanned = packages_scanned, .duration_ms = duration, .security_scanner = security_scanner, .allocator = self.manager.allocator } };
    }
    pub const new = bun.TrivialNew(@This());
    pub const StaticPipeWriter = jsc.Subprocess.NewStaticPipeWriter(@This());
};

pub const SecurityAdvisoryLevel = enum { fatal, warn };
pub const ScanAttemptResult = union(enum) {
    success: SecurityScanResults,
    needs_install: PackageID,
    @"error": anyerror,
};
const scanner_entry_source = @embedFile("./scanner-entry.ts");
const Environment = bun.Environment;
const Output = bun.Output;
const jsc = bun.jsc;
const logger = bun.logger;
const FileSystem = bun.fs.FileSystem;
const DependencyID = bun.install.DependencyID;
const PackageID = bun.install.PackageID;
const PackageManager = bun.install.PackageManager;
const invalid_dependency_id = bun.install.invalid_dependency_id;
const invalid_package_id = bun.install.invalid_package_id;

pub fn doPartialInstallOfSecurityScanner(manager: *PackageManager, ctx: bun.cli.Command.Context, log_level: bun.install.PackageManager.Options.LogLevel, security_scanner_pkg_id: PackageID, original_cwd: []const u8) !void {
        const wf_pair = try InstallWithManager.getWorkspaceFilters(manager, original_cwd);
        const workspace_filters = wf_pair[0];
        const install_root_dependencies = wf_pair[1];
        defer {
        _ = manager.allocator.free(workspace_filters);
        }
        if ((!manager.options.do.install_packages)) {
            return;
        }
        if ((security_scanner_pkg_id == invalid_package_id)) {
            return error.InvalidPackageID;
        }
        const packages_to_install: ?[]const PackageID = (&.{ security_scanner_pkg_id });
        const summary = (switch (manager.options.node_linker) {
.hoisted, .auto => try HoistedInstall.installHoistedPackages(manager, ctx, workspace_filters, install_root_dependencies, log_level, packages_to_install),
.isolated => try IsolatedInstall.installIsolatedPackages(manager, ctx, install_root_dependencies, workspace_filters, packages_to_install),
});
        if (bun.Environment.isDebug) {
            _ = bun.Output.debugWarn("Partial install summary - success: {d}, fail: {d}, skipped: {d}", .{ summary.success, summary.fail, summary.skipped });
        }
        if ((summary.fail > 0)) {
            return error.PartialInstallFailed;
        }
        if (((summary.success == 0) and (summary.skipped == 0))) {
            return error.NoPackagesInstalled;
        }
}

pub fn performSecurityScanAfterResolution(manager: *PackageManager, command_ctx: bun.cli.Command.Context, original_cwd: []const u8) !?SecurityScanResults {
        const security_scanner = ((manager.options.security_scanner) orelse { return null; });
        if ((manager.options.dry_run or (!manager.options.do.install_packages))) {
            return null;
        }
        const scan_all = ((manager.subcommand == .remove) or (manager.update_requests.len == 0));
        const result = try attemptSecurityScan(manager, security_scanner, scan_all, command_ctx, original_cwd);
        switch (result) {
.success => |scan_results| {
return scan_results;
},
.needs_install => |pkg_id| {
_ = Output.prettyln("<r><yellow>Attempting to install security scanner from npm...<r>", .{});
        _ = try doPartialInstallOfSecurityScanner(manager, command_ctx, manager.options.log_level, pkg_id, original_cwd);
        _ = Output.prettyln("<r><green><b>Security scanner installed successfully.<r>", .{});
        const retry_result = try attemptSecurityScanWithRetry(manager, security_scanner, scan_all, command_ctx, original_cwd, true);
        switch (retry_result) {
.success => |scan_results| {
return scan_results;
},
.needs_install => {
return error.SecurityScannerRetryFailed;
},
.@"error" => |e| {
return e;
},
}
},
.@"error" => |e| {
return e;
},
}
}

pub fn performSecurityScanForAll(manager: *PackageManager, command_ctx: bun.cli.Command.Context, original_cwd: []const u8) !?SecurityScanResults {
        const security_scanner = ((manager.options.security_scanner) orelse { return null; });
        const result = try attemptSecurityScan(manager, security_scanner, true, command_ctx, original_cwd);
        switch (result) {
.success => |scan_results| {
return scan_results;
},
.needs_install => |pkg_id| {
_ = Output.prettyln("<r><yellow>Attempting to install security scanner from npm...<r>", .{});
        _ = try doPartialInstallOfSecurityScanner(manager, command_ctx, manager.options.log_level, pkg_id, original_cwd);
        _ = Output.prettyln("<r><green><b>Security scanner installed successfully.<r>", .{});
        const retry_result = try attemptSecurityScanWithRetry(manager, security_scanner, true, command_ctx, original_cwd, true);
        switch (retry_result) {
.success => |scan_results| {
return scan_results;
},
.needs_install => {
return error.SecurityScannerRetryFailed;
},
.@"error" => |e| {
return e;
},
}
},
.@"error" => |e| {
return e;
},
}
}

pub fn printSecurityAdvisories(manager: *PackageManager, results: *const SecurityScanResults) void {
        if ((!results.hasAdvisories())) {
            return;
        }
        const pkgs = manager.lockfile.packages.slice();
        const pkg_names = pkgs.items(.name);
        const string_buf = manager.lockfile.buffers.string_bytes.items;
        for (cp_iter_slice(results.advisories)) |advisory| {
            _ = &advisory;
            _ = Output.print("\n", .{});
            switch (advisory.level) {
.fatal => {
_ = Output.pretty("  <red>FATAL<r>: {s}\n", .{ advisory.package });
},
.warn => {
_ = Output.pretty("  <yellow>WARNING<r>: {s}\n", .{ advisory.package });
},
}
            if (advisory.pkg_path) |pkg_path| {
                _ = &pkg_path;
                if ((pkg_path.len > 1)) {
                    _ = Output.pretty("    <d>via ", .{});
                    var idx: usize = 0;
                    _ = &idx;
                    while ((idx < (pkg_path.len - 1))) : (idx = (idx + 1)) {
                        const ancestor_id = pkg_path[@as(usize, @intCast(idx))];
                        if ((idx > 0)) {
                            _ = Output.pretty(" › ", .{});
                        }
                        const ancestor_name = pkg_names[@as(usize, @intCast(ancestor_id))].slice(string_buf);
                        _ = Output.pretty("{s}", .{ ancestor_name });
                    }
                    _ = Output.pretty(" › <red>{s}<r>\n", .{ advisory.package });
                } else {
                    _ = Output.pretty("    <d>(direct dependency)<r>\n", .{});
                }
            }
            if (advisory.description) |desc| {
                _ = &desc;
                if ((desc.len > 0)) {
                    _ = Output.pretty("    {s}\n", .{ desc });
                }
            }
            if (advisory.url) |url| {
                _ = &url;
                if ((url.len > 0)) {
                    _ = Output.pretty("    <cyan>{s}<r>\n", .{ url });
                }
            }
        }
        _ = Output.print("\n", .{});
        const total = (results.fatal_count + results.warn_count);
        if ((total == 1)) {
            if ((results.fatal_count == 1)) {
                _ = Output.pretty("<b>1 advisory (<red>1 fatal<r>)<r>\n", .{});
            } else {
                _ = Output.pretty("<b>1 advisory (<yellow>1 warning<r>)<r>\n", .{});
            }
        } else {
            if (((results.fatal_count > 0) and (results.warn_count > 0))) {
                _ = Output.pretty("<b>{d} advisories (<red>{d} fatal<r>, <yellow>{d} warning{s}<r>)<r>\n", .{ total, results.fatal_count, results.warn_count, (if ((results.warn_count == 1)) "" else "s") });
            } else {
                if ((results.fatal_count > 0)) {
                    _ = Output.pretty("<b>{d} advisories (<red>{d} fatal<r>)<r>\n", .{ total, results.fatal_count });
                } else {
                    _ = Output.pretty("<b>{d} advisories (<yellow>{d} warning{s}<r>)<r>\n", .{ total, results.warn_count, (if ((results.warn_count == 1)) "" else "s") });
                }
            }
        }
}

pub fn promptForWarnings() bool {
        const can_prompt = Output.isStdinTTY();
        if ((!can_prompt)) {
            _ = Output.pretty("\n<red>Security warnings found. Cannot prompt for confirmation (no TTY).<r>\n", .{});
            _ = Output.pretty("<red>Installation cancelled.<r>\n", .{});
            return false;
        }
        _ = Output.pretty("\n<yellow>Security warnings found.<r> Continue anyway? [y/N] ", .{});
        _ = Output.flush();
        var stdin = std.fs.File.stdin();
        _ = &stdin;
        var reader_buffer: [1024]u8 = undefined;
        _ = &reader_buffer;
        var buffered = stdin.readerStreaming((&reader_buffer));
        _ = &buffered;
        const reader = (&buffered.interface);
        const first_byte_res = (blk_catch_3: { break :blk_catch_3 ((reader.takeByte()) catch |__ce_3| { _ = &__ce_3; break :blk_catch_3 null; }); });
        if ((first_byte_res == null)) {
            _ = Output.pretty("\n<red>Installation cancelled.<r>\n", .{});
            return false;
        }
        const first_byte = first_byte_res.?;
        const should_continue = (switch (first_byte) {
10 => false,
13 => blk: {
        const next_byte = (blk_catch_4: { break :blk_catch_4 ((reader.takeByte()) catch |__ce_4| { _ = &__ce_4; break :blk_catch_4 null; }); });
        if ((next_byte == null)) {
            break :blk false;
        }
        break :blk ((next_byte.? == 10) and false);
},
'y', 'Y' => blk: {
        const next_byte = (blk_catch_5: { break :blk_catch_5 ((reader.takeByte()) catch |__ce_5| { _ = &__ce_5; break :blk_catch_5 null; }); });
        if ((next_byte == null)) {
            break :blk false;
        }
        if ((next_byte.? == 10)) {
            break :blk true;
        } else {
            if ((next_byte.? == 13)) {
                const second_byte = (blk_catch_6: { break :blk_catch_6 ((reader.takeByte()) catch |__ce_6| { _ = &__ce_6; break :blk_catch_6 null; }); });
                if ((second_byte == null)) {
                    break :blk false;
                }
                break :blk (second_byte.? == 10);
            }
        }
        break :blk false;
},
else => blk: {
        while ((blk_catch_7: { break :blk_catch_7 ((reader.takeByte()) catch |__ce_7| { _ = &__ce_7; break :blk_catch_7 null; }); })) |b| {
            if (((b == 10) or (b == 13))) {
                break;
            }
        }
        break :blk false;
},
});
        if ((!should_continue)) {
            _ = Output.pretty("\n<red>Installation cancelled.<r>\n", .{});
            return false;
        }
        _ = Output.pretty("\n<yellow>Continuing with installation...<r>\n\n", .{});
        return true;
}

pub fn attemptSecurityScan(manager: *PackageManager, security_scanner: []const u8, scan_all: bool, command_ctx: bun.cli.Command.Context, original_cwd: []const u8) !ScanAttemptResult {
        return attemptSecurityScanWithRetry(manager, security_scanner, scan_all, command_ctx, original_cwd, false);
}

pub fn attemptSecurityScanWithRetry(manager: *PackageManager, security_scanner: []const u8, scan_all: bool, command_ctx: bun.cli.Command.Context, original_cwd: []const u8, is_retry: bool) !ScanAttemptResult {
        if ((manager.options.log_level == .verbose)) {
            _ = Output.prettyErrorln("<d>[SecurityProvider]<r> Running at '{s}'", .{ security_scanner });
            _ = Output.prettyErrorln("<d>[SecurityProvider]<r> top_level_dir: '{s}'", .{ FileSystem.instance.top_level_dir });
            _ = Output.prettyErrorln("<d>[SecurityProvider]<r> original_cwd: '{s}'", .{ original_cwd });
        }
        const start_time = std.time.milliTimestamp();
        const finder = ScannerFinder{ .manager = manager, .scanner_name = security_scanner };
        _ = try finder.validateNotInWorkspaces();
        const security_scanner_pkg_id = finder.findInRootDependencies();
        const suppress_error_output = (manager.options.log_level != .verbose);
        var collector = PackageCollector.init(manager);
        _ = &collector;
        defer {
        _ = collector.deinit();
        }
        if (scan_all) {
            _ = try collector.collectAllPackages();
        } else {
            _ = try collector.collectUpdatePackages();
        }
        _ = try collector.processQueue();
        const json_builder = JSONBuilder{ .manager = manager, .collector = (&collector) };
        const json_data = try json_builder.buildPackageJSON();
        defer {
        _ = manager.allocator.free(json_data);
        }
        var code: std.ArrayList(u8) = .{};
        _ = &code;
        defer {
        _ = code.deinit(manager.allocator);
        }
        var temp_source: []const u8 = scanner_entry_source;
        _ = &temp_source;
        const scanner_placeholder: []const u8 = "__SCANNER_MODULE__";
        if (std.mem.indexOf(u8, temp_source, scanner_placeholder)) |index| {
            _ = &index;
            _ = try code.appendSlice(manager.allocator, temp_source[0..index]);
            _ = try code.appendSlice(manager.allocator, security_scanner);
            _ = try code.appendSlice(manager.allocator, temp_source[(index + scanner_placeholder.len)..]);
            temp_source = code.items;
        }
        const suppress_placeholder: []const u8 = "__SUPPRESS_ERROR__";
        if (std.mem.indexOf(u8, temp_source, suppress_placeholder)) |index| {
            _ = &index;
            var new_code: std.ArrayList(u8) = .{};
            _ = &new_code;
            _ = try new_code.appendSlice(manager.allocator, temp_source[0..index]);
            _ = try new_code.appendSlice(manager.allocator, (if (suppress_error_output) "true" else "false"));
            _ = try new_code.appendSlice(manager.allocator, temp_source[(index + suppress_placeholder.len)..]);
            _ = code.deinit(manager.allocator);
            code = new_code;
        }
        var scanner = SecurityScanSubprocess.new(.{ .manager = manager, .code = try manager.allocator.dupe(u8, code.items), .json_data = try manager.allocator.dupe(u8, json_data), .ipc_data = undefined, .stderr_data = undefined });
        _ = &scanner;
        defer {
        {
            _ = manager.allocator.free(scanner.code);
            _ = manager.allocator.free(scanner.json_data);
            if (scanner.process) |p| {
                _ = &p;
                _ = p.detach();
                _ = p.deref();
            }
            _ = bun.destroy(scanner);
        }
        }
        _ = try scanner.spawn();
        var closure = ScannerClosure{ .scanner = scanner };
        _ = &closure;
        _ = manager.sleepUntil((&closure), (&@TypeOf(closure).isDone));
        const packages_scanned = collector.dedupe.count();
        return try scanner.handleResults((&collector.package_paths), start_time, packages_scanned, security_scanner, security_scanner_pkg_id, command_ctx, original_cwd, is_retry);
}

pub fn parseSecurityAdvisoriesFromExpr(manager: *PackageManager, advisories_expr: bun.js_parser.Expr, package_paths: *std.AutoArrayHashMap(PackageID,PackagePath)) ![]SecurityAdvisory {
        var advisories_list: std.ArrayList(SecurityAdvisory) = .{};
        _ = &advisories_list;
        defer {
        _ = advisories_list.deinit(manager.allocator);
        }
        if ((advisories_expr.data != .e_array)) {
            _ = Output.errGeneric("Security scanner 'advisories' field must be an array, got: {s}", .{ @tagName(advisories_expr.data) });
            return error.InvalidAdvisoriesFormat;
        }
        const array = advisories_expr.data.e_array;
        const items = array.items.slice();
        var i: usize = 0;
        _ = &i;
        while ((i < items.len)) : (i = (i + 1)) {
            const item = items[@as(usize, @intCast(i))];
            if ((item.data != .e_object)) {
                _ = Output.errGeneric("Security advisory at index {d} must be an object, got: {s}", .{ i, @tagName(item.data) });
                return error.InvalidAdvisoryFormat;
            }
            const item_obj = item.data.e_object;
            const name_expr_opt = item_obj.get("package");
            if ((name_expr_opt == null)) {
                _ = Output.errGeneric("Security advisory at index {d} missing required 'package' field", .{ i });
                return error.MissingPackageField;
            }
            const name_expr = name_expr_opt.?;
            const name_str_temp_opt = name_expr.asString(manager.allocator);
            if ((name_str_temp_opt == null)) {
                _ = Output.errGeneric("Security advisory at index {d} 'package' field must be a string", .{ i });
                return error.InvalidPackageField;
            }
            const name_str_temp = name_str_temp_opt.?;
            if ((name_str_temp.len == 0)) {
                _ = Output.errGeneric("Security advisory at index {d} 'package' field cannot be empty", .{ i });
                return error.EmptyPackageField;
            }
            const name_str = try manager.allocator.dupe(u8, name_str_temp);
            var desc_str: ?[]const u8 = null;
            _ = &desc_str;
            if (item_obj.get("description")) |desc_expr| {
                _ = &desc_expr;
                if (desc_expr.asString(manager.allocator)) |str| {
                    _ = &str;
                    desc_str = try manager.allocator.dupe(u8, str);
                } else {
                    if ((desc_expr.data == .e_null)) {
                        desc_str = null;
                    } else {
                        _ = Output.errGeneric("Security advisory at index {d} 'description' field must be a string or null", .{ i });
                        return error.InvalidDescriptionField;
                    }
                }
            }
            var url_str: ?[]const u8 = null;
            _ = &url_str;
            if (item_obj.get("url")) |url_expr| {
                _ = &url_expr;
                if (url_expr.asString(manager.allocator)) |str| {
                    _ = &str;
                    url_str = try manager.allocator.dupe(u8, str);
                } else {
                    if ((url_expr.data == .e_null)) {
                        url_str = null;
                    } else {
                        _ = Output.errGeneric("Security advisory at index {d} 'url' field must be a string or null", .{ i });
                        return error.InvalidUrlField;
                    }
                }
            }
            const level_expr_opt = item_obj.get("level");
            if ((level_expr_opt == null)) {
                _ = Output.errGeneric("Security advisory at index {d} missing required 'level' field", .{ i });
                return error.MissingLevelField;
            }
            const level_expr = level_expr_opt.?;
            const level_str_opt = level_expr.asString(manager.allocator);
            if ((level_str_opt == null)) {
                _ = Output.errGeneric("Security advisory at index {d} 'level' field must be a string", .{ i });
                return error.InvalidLevelField;
            }
            const level_str = level_str_opt.?;
            const level = (if (std.mem.eql(u8, level_str, "fatal")) SecurityAdvisoryLevel.fatal else (if (std.mem.eql(u8, level_str, "warn")) SecurityAdvisoryLevel.warn else ({
            _ = Output.errGeneric("Security advisory at index {d} 'level' field must be 'fatal' or 'warn', got: '{s}'", .{ i, level_str });
            return error.InvalidLevelValue;
})));
            var pkg_path: ?[]const PackageID = null;
            _ = &pkg_path;
            const pkgs = manager.lockfile.packages.slice();
            const pkg_names = pkgs.items(.name);
            const string_buf = manager.lockfile.buffers.string_bytes.items;
            var j: usize = 0;
            _ = &j;
            while ((j < pkg_names.len)) : (j = (j + 1)) {
                const pkg_name = pkg_names[@as(usize, @intCast(j))];
                if (std.mem.eql(u8, pkg_name.slice(string_buf), name_str)) {
                    const pkg_id: PackageID = @as(PackageID, @truncate(j));
                    if (package_paths.get(pkg_id)) |paths| {
                        _ = &paths;
                        pkg_path = try manager.allocator.dupe(PackageID, paths.pkg_path);
                    }
                    break;
                }
            }
            const advisory = SecurityAdvisory{ .level = level, .package = name_str, .url = url_str, .description = desc_str, .pkg_path = pkg_path };
            _ = try advisories_list.append(manager.allocator, advisory);
        }
        return try advisories_list.toOwnedSlice(manager.allocator);
}
